import type { SchedulingConfig, SchedulingProcess } from '../../types/scheduling'
import { MLQ_LECTURE_PRESET, MLQ_LECTURE_SECOND_PRESET, MLFQ_PRESET_1_2, MLFQ_PRESET_2_3 } from '../../data/schedulingPresets'

export type ExpectedSlice = [string | null, number, number]
export function workload(arrivals: number[], bursts: number[], priorities?: number[], levels?: number[]): SchedulingProcess[] {
  return arrivals.map((arrivalTime, index) => ({
    id: `P${index + 1}`, arrivalTime, burstTime: bursts[index], originalInputOrder: index,
    ...(priorities ? { priority: priorities[index] } : {}), ...(levels ? { queueLevel: levels[index] } : {}),
  }))
}
const a = (levels?: number[]) => workload([3, 5, 8, 0, 12], [4, 9, 4, 7, 6], [2, 1, 2, 1, 1], levels)
const b = (priorities = [2, 2, 1, 2, 1], levels?: number[]) => workload([10, 8, 12, 3, 15], [5, 4, 4, 3, 5], priorities, levels)
export interface LectureExample {
  page: number
  config: SchedulingConfig
  processes: SchedulingProcess[]
  expected: ExpectedSlice[]
  completion: number[]
  lectureCompletion?: number[]
  discrepancy?: string
}

